import string

ALPHABET_SIZE = 26
UPPER_A_ASCII = 65
LOWER_A_ASCII = 97
RAIL_MARK = '\n'
EMPTY_CELL = ''
NEWLINE_MARKER = '\n'

class DecryptionUtils:
    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        self._key = value

    def caesar_decipher(self, ciphertext, shift):
        return ''.join(self._caesar_decrypt_char(char, shift) for char in ciphertext)

    def _caesar_decrypt_char(self, char, shift):
        if not char.isalpha():
            return char
        ascii_offset = UPPER_A_ASCII if char.isupper() else LOWER_A_ASCII
        return chr((ord(char) - ascii_offset - shift) % ALPHABET_SIZE + ascii_offset)

    def vigenere_decipher(self, ciphertext):
        return ''.join(self._vigenere_decipher_helper(ciphertext, key_index=0)[0])

    def _vigenere_decipher_helper(self, ciphertext, key_index):
        decrypted_chars = []
        for char in ciphertext:
            if char.isalpha():
                shift = self._get_vigenere_shift(key_index)
                decrypted_char = self._vigenere_decrypt_char(char, shift)
                decrypted_chars.append(decrypted_char)
                key_index += 1
            else:
                decrypted_chars.append(char)
        return decrypted_chars, key_index

    def _get_vigenere_shift(self, key_index):
        key_char = self.key[key_index % len(self.key)].lower()
        return ord(key_char) - LOWER_A_ASCII

    def _vigenere_decrypt_char(self, char, shift):
        lower_char = char.lower()
        decrypted_lower = chr((ord(lower_char) - LOWER_A_ASCII - shift) % ALPHABET_SIZE + LOWER_A_ASCII)
        return decrypted_lower.upper() if char.isupper() else decrypted_lower

    def rail_fence_decipher(self, encrypted_text, rails):
        fence = self._build_rail_fence_pattern(len(encrypted_text), rails)
        self._fill_rail_fence(fence, encrypted_text)
        return self._read_rail_fence(fence, len(encrypted_text), rails)

    def _build_rail_fence_pattern(self, length, rails):
        fence = [[EMPTY_CELL for _ in range(length)] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction

            fence[row][col] = RAIL_MARK
            col += 1
            row += direction

        return fence

    def _fill_rail_fence(self, fence, encrypted_text):
        index = 0
        for i in range(len(fence)):
            for j in range(len(fence[0])):
                if fence[i][j] == RAIL_MARK:
                    fence[i][j] = encrypted_text[index]
                    index += 1

    def _read_rail_fence(self, fence, length, rails):
        plain_text = []
        direction = -1
        row, col = 0, 0
        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction

            plain_text.append(fence[row][col])
            col += 1
            row += direction

        return ''.join(plain_text)
